from itertools import product

# Explicit finite inputs; alter CASES to test other specified positive pairs.
CASES = [(i, j) for i in range(1, 6) for j in range(1, 6)]
WITNESS = (2, 3)

def trim(a):
    a = tuple(a)
    while a and a[-1] == 0:
        a = a[:-1]
    return a

def size(a):
    return sum(a)

def pad(a, n):
    return tuple(a) + (0,) * (n - len(a))

def contains(mu, lam):
    n = max(len(mu), len(lam))
    return all(a >= b for a, b in zip(pad(mu, n), pad(lam, n)))

def partitions_in_box(q, r):
    # All partitions with at most r parts and largest part at most q.
    out = []
    def rec(prefix, ceiling, left):
        if left == 0:
            out.append(trim(prefix))
            return
        for a in range(ceiling, -1, -1):
            rec(prefix + (a,), a, left - 1)
    rec((), q, r)
    return out

def interval_partitions(i, j):
    base = (i,) * j
    return [mu for mu in partitions_in_box(i + 1, j + 1)
            if contains(mu, base)]

def P(i, j, x, y):
    return trim((i + 1,) * x + (i,) * (j - x) + ((y,) if y else ()))

def one_box_extensions(lam, interval):
    # Independent degree-and-containment enumeration of all one-box extensions.
    return [mu for mu in interval if contains(mu, lam) and size(mu) == size(lam) + 1]

def determinant(A):
    # Exact Leibniz determinant; determinant([])=1 by convention.
    n = len(A)
    assert all(len(row) == n for row in A)
    if n == 0:
        return 1
    ans = 0
    for perm in product(range(n), repeat=n):
        if len(set(perm)) != n:
            continue
        inv = sum(perm[a] > perm[b] for a in range(n) for b in range(a + 1, n))
        ans += (-1 if inv % 2 else 1) * product(A[row][perm[row]] for row in range(n))
    return ans

def fmt(parts):
    return '[' + ', '.join(str(x) for x in parts) + ']'

def check(i, j, emit=False):
    assert i >= 1 and j >= 1
    b = min(i, j)
    d = i * j
    interval = interval_partitions(i, j)
    column_tests = extension_tests = determinant_tests = 0
    if emit:
        print('WITNESS: i=%d j=%d b=%d d=%d' % (i, j, b, d))
    for k in range(b + 1):
        actual = [mu for mu in interval if size(mu) == d + k]
        expected = [P(i, j, x, k - x) for x in range(k + 1)]
        assert set(actual) == set(expected) and len(actual) == len(expected), (i, j, k, actual, expected)
        column_tests += 1
        # Rows are indexed by C_x+C_{x+1}, x=0,...,k-1, in C_0,...,C_k order.
        R = []
        for x in range(k):
            lam = P(i, j, x, k - 1 - x)
            actual_ext = one_box_extensions(lam, interval)
            expected_ext = [P(i, j, x + 1, k - 1 - x), P(i, j, x, k - x)]
            assert set(actual_ext) == set(expected_ext) and len(actual_ext) == 2, (i, j, k, x, actual_ext, expected_ext)
            R.append([1 if col == expected_ext[0] or col == expected_ext[1] else 0 for col in expected])
            extension_tests += 1
        # Delete C_0 (retain C_0), then delete C_k (retain C_k).
        left = [row[1:] for row in R]
        right = [row[:-1] for row in R]
        dl, dr = determinant(left), determinant(right)
        assert dl == 1 and dr == 1, (i, j, k, R, dl, dr)
        determinant_tests += 2
        if emit:
            print('k=%d columns=%s' % (k, fmt(expected)))
            print('k=%d rows=%s' % (k, R))
            print('k=%d delete-C0=%s det=%d; delete-Ck=%s det=%d' % (k, left, dl, right, dr))
    return column_tests, extension_tests, determinant_tests

totals = [0, 0, 0]
for i, j in CASES:
    got = check(i, j, emit=((i, j) == WITNESS))
    totals = [a + b for a, b in zip(totals, got)]
print('CASES:', CASES)
print('COLUMN_LIST_CHECKS:', totals[0])
print('ONE_BOX_EXTENSION_LIST_CHECKS:', totals[1])
print('COMPLEMENTARY_DETERMINANT_CHECKS:', totals[2])
print('RESULT: PASS')
